TLM.f("Sancti/01-13",{"officium":"Commemoratio Baptismatis Domini Nostri Jesu Christi","rule":["ex Sancti/01-06;","Gloria","Credo","Prefatio=Epi"],"ruleInherited":["Gloria","Credo","Prefatio=Epi"],"fallback":"Sancti/01-06","sections":{"Introitus":[{"k":"ref","la":"Malach 3:1; 1 Par 29:12"},{"k":"text","la":"Ecce, advénit dominátor Dóminus: et regnum in manu ejus et potéstas et impérium."},{"k":"ref","la":"Ps 71:1"},{"k":"text","la":"Deus, judícium tuum Regi da: et justítiam tuam Fílio Regis."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ecce, advénit dominátor Dóminus: et regnum in manu ejus et potéstas et impérium."}],"Oratio":[{"k":"text","la":"Deus, cujus Unigénitus in substántia nostræ carnis appáruit: præsta, quǽsumus; ut per eum, quem símilem nobis foris agnóvimus, intus reformári mereámur:"},{"k":"macro","name":"Qui tecum"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Is 60:1-6"},{"k":"text","la":"Surge, illumináre, Jerúsalem: quia venit lumen tuum, et glória Dómini super te orta est. Quia ecce, ténebræ opérient terram et caligo pópulos: super te autem oriétur Dóminus, et glória ejus in te vidébitur. Et ambulábunt gentes in lúmine tuo, et reges in splendóre ortus tui. Leva in circúitu óculos tuos, et vide: omnes isti congregáti sunt, venérunt tibi: fílii tui de longe vénient, et fíliæ tuæ de látere surgent. Tunc vidébis et áfflues, mirábitur et dilatábitur cor tuum, quando convérsa fúerit ad te multitúdo maris, fortitúdo géntium vénerit tibi. Inundátio camelórum opériet te dromedárii Mádian et Epha: omnes de Saba vénient, aurum et thus deferéntes, et laudem Dómino annuntiántes."}],"Graduale":[{"k":"ref","la":"Isa 60:6; 60:1"},{"k":"text","la":"Omnes de Saba vénient, aurum et thus deferéntes, et laudem Dómino annuntiántes."},{"k":"text","la":"Surge et illumináre, Jerúsalem: quia glória Dómini super te orta est. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Matt 2:2"},{"k":"text","la":"Vídimus stellam ejus in Oriénte, et vénimus cum munéribus adoráre Dóminum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joann 1:29-34"},{"k":"text","la":"In illo témpore: Vidit Joánnes Jesum veniéntem ad se, et ait: Ecce Agnus Dei, ecce, qui tollit peccátum mundi. Hic est, de quo dixi: Post me venit vir, qui ante me factus est: quia prior me erat. Et ego nesciébam eum, sed ut manifestétur in Israël, proptérea veni ego in aqua baptízans. Et testimónium perhíbuit Joánnes, dicens: Quia vidi Spíritum descendéntem quasi colúmbam de coelo, et mansit super eum. Et ego nesciébam eum: sed qui misit me baptizáre in aqua, ille mihi dixit: Super quem víderis Spíritum descendéntem, et manéntem super eum, hic est, qui baptízat in Spíritu Sancto. Et ego vidi: et testimónium perhíbui, quia hic est Fílius Dei."}],"Offertorium":[{"k":"ref","la":"Ps 71:10-11"},{"k":"text","la":"Reges Tharsis, et ínsulæ múnera ófferent: reges Arabum et Saba dona addúcent: et adorábunt eum omnes reges terræ, omnes gentes sérvient ei."}],"Secreta":[{"k":"text","la":"Hóstias tibi, Dómine, pro nati Fílii tui apparitióne deférimus, supplíciter exorántes: ut, sicut ipse nostrórum auctor est múnerum, ita sit ipse miséricors et suscéptor, Jesus Christus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Matt 2:2"},{"k":"text","la":"Vídimus stellam ejus in Oriénte, et vénimus cum munéribus adoráre Dóminum."}],"Postcommunio":[{"k":"text","la":"Cœlésti lúmine, quǽsumus, Dómine, semper et ubíque nos præveni: ut mystérium, cujus nos partícipes esse voluísti, et puro cernámus intúitu, et digno percipiámus affectu."},{"k":"macro","name":"Per Dominum"}]},"hr":{"51851082a1fc32e2":{"t":"Mal 3, 1, 1 Ljet 29, 12, Ps 71, 1\n(Mal 3, 1, 1 Ljet 29, 12) Evo, došao je vladar Gospodin. U njegovoj je ruci kraljevstvo i moć i vlast. (Ps 71, 1) Bože, daj Kralju svoju sudačku vlast i svoju pravdu Kraljevu Sinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mal 3, 1, 1 Ljet 29, 12) Evo, došao je vladar Gospodin. U njegovoj je ruci kraljevstvo i moć i vlast.","kn":"(Malak. 3, 1). Eto dođe vladalac Gospodin: kraljevska je čast u ruci .njegovoj i gospo'dstvo. (P.S. 71, 1). Bože, daj kralju suđenje svoje i pravdu svoju Sinu kraljevskom! Slava Ocu . . . Eto dođe . , .","knRef":"Kniewald 1942, str. 68–69 (snimka 35) (OCR)"},"03f32c213961b7a9":{"t":"<i>Pomolimo se</i>.\nBože, budući da se tvoj Jedinorođenac pojavio u našem tijelu, podaj, molimo, da se u duhu obnovimo po njemu koga smo spoznali da nam je sličan u tijelu:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"23852547fbfa640a":{"t":"Iz 60, 1-6\nČitanje Izaije Proroka: Ustani, rasvijetli se, Jeruzaleme, jer je došlo tvoje svjetlo i obasjala te Gospodnja slava. Gle, zemlju će pokriti tama i narode će obaviti mrak, a nad tobom će zasjati Gospodin i na tebi će se vidjeti njegova slava. Narodi će hodati u tvojem svjetlu i kraljevi u sjaju tvoga dolaska. – Podigni svoje oči i gledaj: Svi su se ovi skupili, dolaze k tebi. Tvoji će sinovi doći izdaleka i tvoje kćeri ustat će sa svih strana. Ti ćeš to vidjeti i napunit ćeš se miline, divit će se i širiti tvoje srce, kad se mnoštvo s mora obrati prema tebi i kad silan narod dođe k tebi. Pokrit će te mnoštvo deva, dromedari iz Madijana i Efe. Svi će iz Sabe doći noseći zlato i tamjan i navješćujući Gospodnju slavu.","kn":"Čitanje proroka Izaije (80. 1-6). Ustani, zasvijetli Jeruzaleme, jer je došlo tvoje svijetlo i obasjala te Gospodnja slava. Jer evo, tama će pokriti zemlju i mrak .narode, a nad tobom će zasjati Gospodin i na tebi će se vidjeti njegova slava. 1 hodat će narodi u tvom svijetlu i kraljevi, kada sine tvoje svijetlo. Digni svoje oči 1 gledaj: Svi su se oni skupili i dolaze k tebi. Tvoji će sinovi doći izdaleka i tvoje će kćeri ustati sa strane. Tada ćeš vidjeti i sjati od dragosti, snebivat će se i širiti tvoje srce, na istoku, išla je pred njima, dok nije došla i stala kad mnoštvo s mora krene prema tebi, kada k tebi dođe ^sila naroda. Mnoštvo deva pokrit će te. dromedari iz Medijana i Efe;' svi će dolaziti iz Saibeje i donosit će zlato i tamjan i navještat će hvalu Gospodnju.","knRef":"Kniewald 1942, str. 68–69 (snimka 35) (OCR)"},"1e556b082189917a":{"t":"Iz 60, 6 i 1\nSvi će iz Sabe doći noseći zlato i tamjan i navješćujući Gospodnju slavu. Ustani, rasvijetli se, Jeruzaleme, jer te obasjala Gospodnja slava.\n\nMt 2, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nVidjeli smo njegovu zvijezdu na istoku i dođosmo s darovima da se poklonimo Gospodinu. <i>Aleluja</i>.","kn":"(Is. 60, 6). Svi će iz Sebe doći Zlato i tamjan prinoseći i hvalu Gospodinu javljajući. Ustani, zasvijetli Jeruzaleme: jer sla\\'a te Gospodnja obasja.\n\nAleluja, aleluja. (Mat. 2, 2.) Vidjesmo zvijezdu njegovu na istoku i dodasmo s darovima da se poklonimo Gospodinu, aleluja.","knRef":"Kniewald 1942, str. 70–71 (snimka 36) (OCR)"},"e049968d6411885b":{"t":"Iv 1, 29-34\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme: vidje Ivan da Isus dolazi k njemu i reče: Evo, Jaganjac Božji, evo koji uzima grijehe svijeta! Ovo je onaj za koga sam vam kazao: Poslije mene dolazi čovjek koji je bio prije mene i koji je veći od mene. Ja ga nisam poznavao, nego sam zato došao krstiti vodom da Izrael njega prizna. A Ivan je svjedočio: Vidio sam Duha, kako kao golub silazi s neba i stade na njemu. Ja ga nisam poznavao, nego onaj, koji me posla krstiti vodom, reče mi: Na koga vidiš da silazi Duh i da ostaje na njemu, taj je koji krsti Duhom Svetim. Vidio sam i svjedočim da je to Sin Božji.","kn":"t Slijedi sv. evanđelje po Ivanu (1, 29-34). U ono vrijeme: vide Ivan Isusa, gdje dolazi k njemu i reče: Evo, Janje Božje, što oduzima grijehe svijeta. Ovo je onaj, za koga sam rekao: Zia^ mnom dolazi čovjek, koji me je pretekao, jer bijaše prije mene. I ja ga nisam poznavao, nego da se objavi Izraelu, zato sam ja došao, da krstim vodom. I Ivan je svjedočio govoreći: Promatrao' sam Duha gdje silazi s neba kao golub i stade na njemu., I ja ga nisam poznavao, nego onaj, koji me je poslao, da krstirn vodO'm, on mi reče: Na koiga vidiš da silazi Duh i ostaje na njemu, to je onaj, koji krsti Duhom svetim. I ja sam vidio i svjedočioi, da je ovaj Sin Božji.","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"},"3fc236c7f2696475":{"t":"Ps 71, 10-11\nKraljevi Tarzisa i otoka prinijet će poklone. Kraljevi Arabije i Sabe donijet će darove. Poklonit će mu se svi zemaljski kraljevi, služit će mu svi narodi.","kn":"(Ps. 71, 10-11). Kraljevi će^Tarsa daroue prikazati, kraljevi će arapski donijeti poMone. nijemu će se pokloniti svi kraljevi zemaljski, svi ce narodi služiti njemu.","knRef":"Kniewald 1942, str. 70–71 (snimka 36) (OCR)"},"ae22c7749ff8d917":{"t":"Prikazujemo ti, Gospodine, žrtve na spomen objavljenja tvoga rođenoga Sina i ponizno molimo da milosrdno primi naše darove onaj koji je njihov početnik Isus Krist, Gospodin naš.\n<i>Koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prikazujemo Ti, Gospodine, žrtve u spomen, što nam se Tvoj Sin ukazao, postavši čovjekom, i ponizno Te molimo, da On u svomie milosrđu primi naše diarove, jer je On početnik, Isus Krist, Gospodin naš, 'koji s Tobom živi i kraljuje...","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"},"93e8203b4ea3a0a5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože: – jer kad se tvoj Jedinorođenac pojavio u našem smrtnom tijelu, on nas je novim svjetlom svoje besmrtnosti obnovio. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vječni Bože, jer je otajstvom utjelovljene Riječi očima naše duše zasjalo novo svijetlo Tvoje sjajnosti, te nas Bog, dok ga spoznajemo u vidljivom obličju, privlači da ljubimo i nevidljive stvari. I zato pjevamo pjesmu slave Tvoje s anđelima i arkanđelima, s prijestolima 1 s gospodstvima, sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"a30154876acf1133":{"t":"Mt 2, 2\nVidjeli smo njegovu zvijezdu na istoku i dođosmo s darovima da se poklonimo Gospodinu.","kn":"(Mat. 2, 2). Vidjesmo zvijezdu na istoku i dođosmo s darovima da se poklonimo Gospodinu.","knRef":"Kniewald 1942, str. 70–71 (snimka 36) (OCR)"},"a56b18f7515affa4":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da bude uvijek i svagdje pred nama nebesko svjetlo, te čistim pogledom promatramo i dostojnom ljubavlju primamo otajstvo u kojem hoćeš da sudjelujemo.\n<i>Per Dóminum nostrum Iesum Christum, Fílium tuum: Qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus: per ómnia saecula saéculórum</i>.","kn":"Molimo, Gospodine, pretječi nas uvijek i svagdje nebeskom svjetlošću, da čistim okom gledamo tajnu, koje si htio da budemo dionici i da je primamo dostojnim (poštivanjem, po G. n. I. K. , Velika se misao Bogojavljenja ističe i dalje razvija “ „Jj’^ šest nedjelja poslije svetkovine svetih triju Kralja. U posla nicama govori apostol naroda sv Pavao. A u danasnjein se evanđelju javlja dvanaestgodišnji Isus kao Sin nebeskoga Uca, kao Mudrost Božja. ,, Budući da se po odredbi Pape Pija XI. u nedjelju u osmini Bogojavljenja slavi svetkovina sv. Obitelji, to se današnja nedjelja spominje samo u molitvama, a čitav se ovaj miisni obrazac čita u misi narednoga dana. Padne li ova nedjelja na dan 13. siječnja (osmina Bogojavljenja), tada se","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"}}});
